340                                         logic [4:0]  dest,
341                                         logic [4:0]  base,
342                                         logic [11:0] offset);
343     // OpCode Load
344     return {offset[11:0], base, size, dest, 7'h03};
345   endfunction
346 
347   function automatic logic [31:0] auipc (logic [4:0]  rd,
348                                          logic [20:0] imm);
