375   endfunction
376 
377   function automatic logic [31:0] csrw (csr_reg_t   csr,
378                                         logic [4:0] rs1);
379     // CSRRW, rd, OpCode System
380     return {csr, rs1, 3'h1, 5'h0, 7'h73};
381   endfunction
382 
383   function automatic logic [31:0] csrr (csr_reg_t   csr,
384                                         logic [4:0] dest);
385     // rs1, CSRRS, rd, OpCode System
