387   endfunction
388 
389   function automatic logic [31:0] branch(logic [4:0]  src2,
390                                          logic [4:0]  src1,
391                                          logic [2:0]  funct3,
392                                          logic [11:0] offset);
393     // OpCode Branch
394     return {offset[11], offset[9:4], src2, src1, funct3,
395         offset[3:0], offset[10], 7'b11_000_11};
396   endfunction
